import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define TILE_H 16
#define TILE_W 16
__global__ void conv3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int H, int W, int D,
    int out_H, int out_W, int out_D,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    int groups,
    int ext_H,
    int ext_W)
{
    extern __shared__ float smem[];
    int in_channels_per_group = in_channels / groups;
    int out_channels_per_group = out_channels / groups;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int w_tile_out_start = blockIdx.x * TILE_W;
    int h_tile_out_start = blockIdx.y * TILE_H;
    int bd = blockIdx.z;
    int b = bd / out_D;
    int d_out = bd % out_D;
    int h_out = h_tile_out_start + ty;
    int w_out = w_tile_out_start + tx;
    int d_in = d_out * stride - padding;
    bool d_valid = (d_in >= 0 && d_in < D);
    int h_tile_start = h_tile_out_start * stride - padding;
    int w_tile_start = w_tile_out_start * stride - padding;
    int tid = ty * blockDim.x + tx;
    int total_threads = blockDim.x * blockDim.y;
    bool out_valid = (h_out < out_H && w_out < out_W);
    for (int g = 0; g < groups; ++g) {
        int ci_start = g * in_channels_per_group;
        int tile_size = in_channels_per_group * ext_H * ext_W;
        if (d_valid) {
            for (int i = tid; i < tile_size; i += total_threads) {
                int rem = i;
                int wc = rem % ext_W; rem /= ext_W;
                int hc = rem % ext_H; rem /= ext_H;
                int c = rem;
                int h_in = h_tile_start + hc;
                int w_in = w_tile_start + wc;
                float val = 0.0f;
                if (h_in >= 0 && h_in < H && w_in >= 0 && w_in < W) {
                    int actual_ci = ci_start + c;
                    long input_idx = ((((long)b * D + d_in) * in_channels + actual_ci) * H + h_in) * W + w_in;
                    val = input[input_idx];
                }
                smem[i] = val;
            }
        } else {
            for (int i = tid; i < tile_size; i += total_threads) {
                smem[i] = 0.0f;
            }
        }
        __syncthreads();
        if (out_valid) {
            for (int co_local = 0; co_local < out_channels_per_group; ++co_local) {
                int co = g * out_channels_per_group + co_local;
                float acc = 0.0f;
                for (int c = 0; c < in_channels_per_group; ++c) {
                    const float* smem_c = smem + c * ext_H * ext_W;
                    for (int kh = 0; kh < kernel_size; ++kh) {
                        int hc = ty * stride + kh * dilation;
                        const float* smem_row = smem_c + hc * ext_W;
                        for (int kw = 0; kw < kernel_size; ++kw) {
                            int wc = tx * stride + kw * dilation;
                            float v = smem_row[wc];
                            long weight_idx = ((((long)co * in_channels_per_group + c) * kernel_size + kh) * kernel_size + kw) * 1 + 0;
                            acc += v * weight[weight_idx];
                        }
                    }
                }
                long output_idx = ((((long)b * out_D + d_out) * out_channels + co) * out_H + h_out) * out_W + w_out;
                output[output_idx] = acc;
            }
        }
        __syncthreads();
    }
}
torch::Tensor conv3d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    int stride,
    int padding,
    int dilation,
    int groups)
{
    input = input.contiguous();
    weight = weight.contiguous();
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int D = input.size(4);
    int out_channels = weight.size(0);
    int kernel_size = weight.size(2);
    int out_H = (H + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int out_W = (W + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int out_D = (D + 2 * padding - dilation * (1 - 1) - 1) / stride + 1;
    // Permute input so that D (originally fastest-varying) becomes a
    // leading batch-like dimension, allowing coalesced accesses along W
    // for each fixed depth slice processed by a CUDA block.
    auto input_perm = input.permute({0, 4, 1, 2, 3}).contiguous();
    auto output_perm = torch::zeros({batch_size, out_D, out_channels, out_H, out_W}, input.options());
    int in_channels_per_group = in_channels / groups;
    int ext_H = (TILE_H - 1) * stride + (kernel_size - 1) * dilation + 1;
    int ext_W = (TILE_W - 1) * stride + (kernel_size - 1) * dilation + 1;
    dim3 block(TILE_W, TILE_H);
    dim3 grid(
        (out_W + TILE_W - 1) / TILE_W,
        (out_H + TILE_H - 1) / TILE_H,
        batch_size * out_D
    );
    size_t shared_bytes = (size_t)in_channels_per_group * ext_H * ext_W * sizeof(float);
    if (shared_bytes > 48 * 1024) {
        cudaFuncSetAttribute(conv3d_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)shared_bytes);
    }
    conv3d_kernel<<<grid, block, shared_bytes>>>(
        input_perm.data_ptr<float>(),
        weight.data_ptr<float>(),
        output_perm.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        H, W, D,
        out_H, out_W, out_D,
        kernel_size,
        stride,
        padding,
        dilation,
        groups,
        ext_H,
        ext_W
    );
    auto output = output_perm.permute({0, 2, 3, 4, 1}).contiguous();
    return output;
}
"""

conv3d_cpp_source = r"""
torch::Tensor conv3d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    int stride,
    int padding,
    int dilation,
    int groups);
"""

conv3d_module = load_inline(
    name="conv3d_module",
    cpp_sources=conv3d_cpp_source,
    cuda_sources=conv3d_source,
    functions=["conv3d_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a 3D convolution with an asymmetric input and a square kernel
    (kernel_size, kernel_size, 1) using a custom CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.use_bias = bias

        assert in_channels % groups == 0
        assert out_channels % groups == 0

        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size, 1)
        )
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.weight.cuda().contiguous()

        out = conv3d_module.conv3d_forward(
            x, weight,
            self.stride,
            self.padding,
            self.dilation,
            self.groups
        )

        if self.bias is not None:
            out = out + self.bias.view(1, -1, 1, 1, 1)

        return out


batch_size = 16
in_channels = 3
out_channels = 64
kernel_size = 3
width = 256
height = 256
depth = 10


def get_inputs():
    x = torch.rand(batch_size, in_channels, height, width, depth)
    return [x]


def get_init_inputs():
    return [in_channels, out_channels, kernel_size]

